class Solution {
public:
    vector<vector<int>> seePeople(vector<vector<int>>& heights) {
        int m = heights.size();
        int n = heights[0].size();

        vector<vector<int>> ans(m, vector<int>(n, 0));

        // Step 1: Count visible people to the right.
        for (int i = 0; i < m; ++i) {
            stack<int> st;

            for (int j = n - 1; j >= 0; --j) {
                int h = heights[i][j];

                // All shorter people on stack are visible.
                while (!st.empty() && st.top() < h) {
                    ++ans[i][j];
                    st.pop();
                }

                // First taller/equal person is visible.
                if (!st.empty()) {
                    ++ans[i][j];

                    // Equal heights block further visibility.
                    if (st.top() == h) {
                        st.pop();
                    }
                }

                st.push(h);
            }
        }

        // Step 2: Count visible people below.
        for (int j = 0; j < n; ++j) {
            stack<int> st;

            for (int i = m - 1; i >= 0; --i) {
                int h = heights[i][j];

                while (!st.empty() && st.top() < h) {
                    ++ans[i][j];
                    st.pop();
                }

                if (!st.empty()) {
                    ++ans[i][j];

                    if (st.top() == h) {
                        st.pop();
                    }
                }

                st.push(h);
            }
        }

        return ans;
    }
};
